using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class FluidRuntimeOperations:RefCounted
{
    private static Resource? ResourceValue(Variant value)=>value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;
    private readonly FluidSettingsOperations _settings=new();private readonly FluidSurfaceOperations _surface=new();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public void ready(Node3D owner){var surface=new MeshInstance3D{Name="LiquidSurface"};owner.Set("surface",surface);owner.Get("content").As<Node>().AddChild(surface);surface.TopLevel=true;surface.GlobalTransform=Transform3D.Identity;surface.Layers=1;var material=new ShaderMaterial{Shader=GD.Load<Shader>("res://scripts/actors/physics/fluid/fluid.gdshader")};owner.Set("liquid_material",material);surface.MaterialOverride=material;}
    public void evaluate(Node3D owner,double time,Settings values){var surface=owner.Get("surface").AsGodotObject() as MeshInstance3D;if(surface==null)return;if(!Get(Get(values,"physics",new Settings()).AsGodotDictionary(),"enabled",true).AsBool())clear_surface(owner);var reference=ResourceValue(Get(values,"fluid_material"));if(ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd"))owner.Call("_apply_material_reference",reference!,default(Variant),false);else{var material=owner.Get("liquid_material").As<ShaderMaterial>();surface.MaterialOverride=material;foreach(var pair in new[]{new[]{"liquid_color","fluid_color"},new[]{"foam_color","fluid_foam_color"},new[]{"opacity","fluid_opacity"},new[]{"roughness","fluid_roughness"},new[]{"metallic","fluid_metallic"},new[]{"specular","fluid_specular"},new[]{"glow","fluid_emission"},new[]{"foam_amount","fluid_foam"},new[]{"texture_scale","fluid_texture_scale"},new[]{"texture_offset","fluid_texture_offset"},new[]{"texture_flow","fluid_texture_flow"},new[]{"texture_blend","fluid_texture_blend"},new[]{"normal_strength","fluid_normal_strength"}})material.SetShaderParameter(pair[0],Get(values,pair[1]));material.SetShaderParameter("texture_rotation",Mathf.DegToRad(Get(values,"fluid_texture_rotation",0).AsDouble()));foreach(var pair in new[]{new[]{"fluid_texture","detail_texture","has_texture"},new[]{"fluid_normal","normal_texture","has_normal"}}){var texture=owner.Call("_texture_for_value",Get(values,pair[0])).As<Texture2D>();material.SetShaderParameter(pair[1],texture==null?default(Variant):Variant.From(texture));material.SetShaderParameter(pair[2],texture!=null);}material.SetShaderParameter("liquid_time",time);}}
    public void show_state(Node3D owner,Settings state,Settings values){var effective=_settings.effective(values);var foam=Get(state,"fluid_foam",Array.Empty<float>()).AsFloat32Array();long key=(long)GD.Hash(new GArray{state["points"],foam,effective["cell"],values["fluid_surface_level"]});if(owner.Get("surface_key").AsInt64()==key)return;owner.Set("surface_key",key);var stats=_surface.build(state["points"].AsVector3Array(),foam,effective);owner.Set("surface_stats",stats);owner.Get("surface").As<MeshInstance3D>().Mesh=stats["mesh"].As<Mesh>();}
    public void clear_surface(Node3D owner){var surface=owner.Get("surface").AsGodotObject() as MeshInstance3D;if(surface!=null){surface.Mesh=null;owner.Set("surface_key",-1);}}
}
